import { useEffect, useState } from "react";
import { BASE_URL } from "../config/config";


function InventoryDisplay() {
  const [pantry, setPantry] = useState([]);

  useEffect(() => {
    fetch(`${BASE_URL}/api/pantry`)
      .then((res) => res.json())
      .then((data) => setPantry(data))
      .catch((err) => console.error("Failed to fetch pantry:", err));
  }, []);

  const handleAddToStock = (item) => {
    fetch(`${BASE_URL}/api/pantry/${item.ROWID}/add`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quantity: 1 }),
    })
      .then((res) => res.json())
      .then((data) => {
        setPantry((prev) =>
          prev.map((i) => (i.ROWID === item.ROWID ? { ...i, stock: i.stock + 1 } : i))
        );
      })
      .catch((err) => console.error("Failed to add to stock:", err));
  }

  const handleTakeawayFromStock = (item) => {
    fetch(`${BASE_URL}/api/pantry/${item.ROWID}/remove`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quantity: 1 }),
    })
      .then((res) => res.json())
      .then((data) => {
        setPantry((prev) =>
          prev.map((i) => (i.ROWID === item.ROWID ? { ...i, stock: i.stock - 1 } : i))
        );
      })
      .catch((err) => console.error("Failed to remove from stock:", err));
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <h1 className="text-3xl font-bold underline">
Pantry Items</h1>
      <table className="border border-gray-300" cellPadding="8" style={{ borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th className="border border-gray-300">Name</th>
            <th className="border border-gray-300">Type</th>
            <th className="border border-gray-300">Calories</th>
            <th className="border border-gray-300">Serving</th>
            <th className="border border-gray-300">Vegan</th>
            <th className="border border-gray-300">Gluten-Free</th>
            <th className="border border-gray-300">Date Added</th>
            <th className="border border-gray-300">Stock</th>
            <th className="border border-gray-300">Add</th>
            <th className="border border-gray-300">Remove</th>
          </tr>
        </thead>
        <tbody>
          {pantry.map((item) => (
            <tr key={item.ROWID}>
              <td>{item.foodName}</td>
              <td>{item.foodType}</td>
              <td>{item.Calories}</td>
              <td>{item.servingSize}</td>
              <td>{item.ifVegan ? "✅" : "❌"}</td>
              <td>{item.isGlutenFree ? "✅" : "❌"}</td>
              <td>{item.dateAdded}</td>
              <td>{item.stock}</td>
              <td>
                <button onClick={() => handleAddToStock(item)}>Add</button>
              </td>
              <td>
                <button onClick={() => handleTakeawayFromStock(item)}>Remove</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default InventoryDisplay;
